/**
 * Network Incident Escalation Flow
 *
 * This flow processes overdue Network incidents with escalation issues:
 * 1. Runs on a scheduled basis (daily at 9 AM)
 * 2. Looks up all active Network incidents with overdue escalation
 * 3. Iterates through each incident and:
 *    - Logs the short description
 *    - Sends notification to the incident owner
 *    - Posts the short description to Slack (via notification)
 * 4. All communications happen in parallel for each incident
 *
 * Note: Slack integration requires a configured notification template
 * that includes Slack webhook integration.
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const networkIncidentEscalationFlow = Flow(
    {
        $id: Now.ID['network_incident_escalation_flow'],
        name: 'Network Incident Escalation Flow',
        description: 'Processes overdue Network incidents by logging, notifying owners, and posting to Slack',
    },
    wfa.trigger(
        trigger.scheduled.daily,
        { $id: Now.ID['daily_escalation_check_trigger'] },
        {
            time: Time({ hours: 9, minutes: 0, seconds: 0 }),
        }
    ),
    (params) => {
        // Step 1: Log the start of escalation processing
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['log_escalation_start'],
                annotation: 'Log start of escalation processing',
            },
            {
                log_level: 'info',
                log_message: `Starting Network incident escalation processing at ${wfa.dataPill(params.trigger.run_start_date_time, 'datetime')}`,
            }
        )

        // Step 2: Look up all active Network incidents with overdue escalation
        const overdueIncidents = wfa.action(
            action.core.lookUpRecords,
            {
                $id: Now.ID['lookup_overdue_network_incidents'],
                annotation: 'Retrieve all active Network incidents with overdue escalation',
            },
            {
                table: 'incident',
                conditions: 'active=true^category=network^escalation!=0^due_dateLT@javascript:gs.nowDateTime()',
                max_results: 1000,
                sort_column: 'due_date',
                sort_type: 'sort_asc',
            }
        )

        // Step 3: Log the count of overdue incidents found
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['log_overdue_count'],
                annotation: 'Log number of overdue Network incidents found',
            },
            {
                log_level: 'warn',
                log_message: `Found ${wfa.dataPill(overdueIncidents.Count, 'integer')} overdue Network incidents with escalation`,
            }
        )

        // Step 4: Check if any overdue incidents were found
        wfa.flowLogic.if(
            {
                condition: `${wfa.dataPill(overdueIncidents.Count, 'integer')}>0`,
                annotation: 'Check if overdue incidents exist',
                $id: Now.ID['check_overdue_incidents_exist'],
            },
            () => {
                // Step 5: Iterate through each overdue incident
                wfa.flowLogic.forEach(
                    wfa.dataPill(overdueIncidents.Records, 'array.string'),
                    {
                        $id: Now.ID['foreach_overdue_incident'],
                        annotation: 'Process each overdue Network incident',
                    },
                    () => {
                        // Look up the full incident details for current iteration
                        const incidentDetails = wfa.action(
                            action.core.lookUpRecord,
                            {
                                $id: Now.ID['lookup_incident_details'],
                                annotation: 'Retrieve incident details including owner',
                            },
                            {
                                table: 'incident',
                                conditions: `sys_id=${wfa.dataPill(overdueIncidents.Records, 'array.string')}`,
                            }
                        )

                        // Step 5a: Log the short description of the incident
                        wfa.action(
                            action.core.log,
                            {
                                $id: Now.ID['network_log_incident_short_description'],
                                annotation: 'Log incident short description',
                            },
                            {
                                log_level: 'warn',
                                log_message: `Overdue Network Incident - Number: ${wfa.dataPill(incidentDetails.Record.number, 'string')}, Short Description: ${wfa.dataPill(incidentDetails.Record.short_description, 'string')}, Owner: ${wfa.dataPill(incidentDetails.Record.assigned_to, 'string')}, Due Date: ${wfa.dataPill(incidentDetails.Record.due_date, 'string')}`,
                            }
                        )

                        // Step 5b: Send notification to the incident owner (in parallel)
                        wfa.action(
                            action.core.sendNotification,
                            {
                                $id: Now.ID['send_owner_notification'],
                                annotation: 'Send escalation notification to incident owner',
                            },
                            {
                                table_name: 'incident',
                                record: `${wfa.dataPill(incidentDetails.Record.sys_id, 'reference')}`,
                                notification: 'overdue_network_incident_owner_notification',
                            }
                        )

                        // Step 5c: Post to Slack via notification (in parallel)
                        wfa.action(
                            action.core.sendNotification,
                            {
                                $id: Now.ID['post_to_slack'],
                                annotation: 'Post incident details to Slack channel',
                            },
                            {
                                table_name: 'incident',
                                record: `${wfa.dataPill(incidentDetails.Record.sys_id, 'reference')}`,
                                notification: 'overdue_network_incident_slack_notification',
                            }
                        )

                        // Step 5d: Update work notes to track escalation processing
                        wfa.action(
                            action.core.updateRecord,
                            {
                                $id: Now.ID['update_incident_work_notes'],
                                annotation: 'Update work notes with escalation notification details',
                            },
                            {
                                table_name: 'incident',
                                record: `${wfa.dataPill(incidentDetails.Record.sys_id, 'reference')}`,
                                values: TemplateValue({
                                    work_notes: `Escalation notification sent to owner ${wfa.dataPill(incidentDetails.Record.assigned_to, 'string')} and posted to Slack. Incident is overdue. Due Date: ${wfa.dataPill(incidentDetails.Record.due_date, 'string')}`,
                                }),
                            }
                        )

                        // Step 5e: Fire event for escalation
                        wfa.action(
                            action.core.fireEvent,
                            {
                                $id: Now.ID['fire_escalation_event'],
                                annotation: 'Fire escalation event for monitoring',
                            },
                            {
                                event_name: 'network.incident.escalation.overdue',
                                table: 'incident',
                                record: `${wfa.dataPill(incidentDetails.Record.sys_id, 'reference')}`,
                                parm1: `${wfa.dataPill(incidentDetails.Record.number, 'string')}`,
                                parm2: `${wfa.dataPill(incidentDetails.Record.short_description, 'string')}`,
                            }
                        )
                    }
                )

                // Step 6: Log completion summary
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['log_processing_complete'],
                        annotation: 'Log escalation processing completion',
                    },
                    {
                        log_level: 'info',
                        log_message: `Completed processing ${wfa.dataPill(overdueIncidents.Count, 'integer')} overdue Network incidents. Notifications sent to owners and Slack posts created.`,
                    }
                )
            }
        )

        // Step 7: Handle case where no overdue incidents exist
        wfa.flowLogic.else(
            {
                annotation: 'Handle no overdue incidents scenario',
                $id: Now.ID['handle_no_overdue_incidents'],
            },
            () => {
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['log_no_overdue_incidents'],
                        annotation: 'Log that no overdue incidents were found',
                    },
                    {
                        log_level: 'info',
                        log_message: 'No overdue Network incidents with escalation found. No action required.',
                    }
                )
            }
        )
    }
)
